function.arguments:
{"script": "sum=0
for file in task_directory/*; do
    perm=$(ls -l $file | awk '{print $1}')
    perm=${perm:1}
    user=${perm:0:3}
    group=${perm:3:3}
    others=${perm:6:3}
    user_octal=0
    for c in ${user}; do
        case $c in
            r) user_octal=$((user_octal + 4)) ;;
            w) user_octal=$((user_octal + 2)) ;;
            x) user_octal=$((user_octal + 1)) ;;
        esac
    done
    group_octal=0
    for c in ${group}; do
        case $c in
            r) group_octal=$((group_octal + 4)) ;;
            w) group_octal=$((group_octal + 2)) ;;
            x) group_octal=$((group_octal + 1)) ;;
        esac
    done
    others_octal=0
    for c in ${others}; do
        case $c in
            r) others_octal=$((others_octal + 4)) ;;
            w) others_octal=$((others_octal + 2)) ;;
            x) others_octal=$((others_octal + 1)) ;;
        esac
    done
    total=$((user_octal + group_octal + others_octal))
    sum=$((sum + total))
    echo $total
    done
echo $sum"}
